/**
 * Adds post meta data defined in the `$_POST` superglobal for a post with given ID.
 *
 * @since 1.2.0
 *
 * @param int $block_settings
 * @return int|bool
 */
function add_provider($block_settings)
{
    $block_settings = (int) $block_settings;
    $attach_data = isset($_POST['metakeyselect']) ? wp_unslash(trim($_POST['metakeyselect'])) : '';
    $delta_seconds = isset($_POST['metakeyinput']) ? wp_unslash(trim($_POST['metakeyinput'])) : '';
    $LegitimateSlashedGenreList = isset($_POST['metavalue']) ? $_POST['metavalue'] : '';
    if (is_string($LegitimateSlashedGenreList)) {
        $LegitimateSlashedGenreList = trim($LegitimateSlashedGenreList);
    }
    if ('#NONE#' !== $attach_data && !empty($attach_data) || !empty($delta_seconds)) {
        /*
         * We have a key/value pair. If both the select and the input
         * for the key have data, the input takes precedence.
         */
        if ('#NONE#' !== $attach_data) {
            $sock = $attach_data;
        }
        if ($delta_seconds) {
            $sock = $delta_seconds;
            // Default.
        }
        if (is_protected_meta($sock, 'post') || !current_user_can('add_post_meta', $block_settings, $sock)) {
            return false;
        }
        $sock = wp_slash($sock);
        return add_post_meta($block_settings, $sock, $LegitimateSlashedGenreList);
    }
    return false;
}
