/**
 * Output the select form for the language selection on the installation screen.
 *
 * @since 4.0.0
 *
 * @global string $normalizedbinary Locale code of the package.
 *
 * @param array[] $comment_content Array of available languages (populated via the Translation API).
 */
function set_current_user($comment_content)
{
    global $normalizedbinary;
    $count_log2 = get_available_languages();
    echo "<label class='screen-reader-text' for='language'>Select a default language</label>\n";
    echo "<select size='14' name='language' id='language'>\n";
    echo '<option value="" lang="en" selected="selected" data-continue="Continue" data-installed="1">English (United States)</option>';
    echo "\n";
    if (!empty($normalizedbinary) && isset($comment_content[$normalizedbinary])) {
        if (isset($comment_content[$normalizedbinary])) {
            $filtered_image = $comment_content[$normalizedbinary];
            printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($filtered_image['language']), esc_attr(current($filtered_image['iso'])), esc_attr($filtered_image['strings']['continue'] ? $filtered_image['strings']['continue'] : 'Continue'), in_array($filtered_image['language'], $count_log2, true) ? ' data-installed="1"' : '', esc_html($filtered_image['native_name']));
            unset($comment_content[$normalizedbinary]);
        }
    }
    foreach ($comment_content as $filtered_image) {
        printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($filtered_image['language']), esc_attr(current($filtered_image['iso'])), esc_attr($filtered_image['strings']['continue'] ? $filtered_image['strings']['continue'] : 'Continue'), in_array($filtered_image['language'], $count_log2, true) ? ' data-installed="1"' : '', esc_html($filtered_image['native_name']));
    }
    echo "</select>\n";
    echo '<p class="step"><span class="spinner"></span><input id="language-continue" type="submit" class="button button-primary button-large" value="Continue" /></p>';
}


