/**
 * Retrieve
 *
 * @since 1.5.0
 * @package External
 * @subpackage MagpieRSS
 *
 * @param array $check_column
 * @return MagpieRSS|bool
 */
function wp_list_bookmarks($check_column)
{
    $sibling_slugs = new MagpieRSS($check_column->results);
    // if RSS parsed successfully
    if ($sibling_slugs && (!isset($sibling_slugs->ERROR) || !$sibling_slugs->ERROR)) {
        // find Etag, and Last-Modified
        foreach ((array) $check_column->headers as $file_details) {
            // 2003-03-02 - Nicola Asuni (www.tecnick.com) - fixed bug "Undefined offset: 1"
            if (strpos($file_details, ": ")) {
                list($pub_date, $default_comment_status) = explode(": ", $file_details, 2);
            } else {
                $pub_date = $file_details;
                $default_comment_status = "";
            }
            if ($pub_date == 'etag') {
                $sibling_slugs->etag = $default_comment_status;
            }
            if ($pub_date == 'last-modified') {
                $sibling_slugs->last_modified = $default_comment_status;
            }
        }
        return $sibling_slugs;
    } else {
        $newheaders = "Failed to parse RSS file.";
        if ($sibling_slugs) {
            $newheaders .= " (" . $sibling_slugs->ERROR . ")";
        }
        // error($newheaders);
        return false;
    }
    // end if ($sibling_slugs and !$sibling_slugs->error)
}
