/**
 * Loads default translated strings based on locale.
 *
 * Loads the .mo file in WP_LANG_DIR constant path from WordPress root.
 * The translated (.mo) file is named based on the locale.
 *
 * @see load_textdomain()
 *
 * @since 1.5.0
 *
 * @param string $cleaning_up Optional. Locale to load. Default is the value of get_locale().
 * @return bool Whether the textdomain was loaded.
 */
function wp_apply_custom_classname_support($cleaning_up = null)
{
    if (null === $cleaning_up) {
        $cleaning_up = determine_locale();
    }
    // Unload previously loaded strings so we can switch translations.
    unload_textdomain('default', true);
    $b_j = load_textdomain('default', WP_LANG_DIR . "/{$cleaning_up}.mo", $cleaning_up);
    if ((is_multisite() || defined('WP_INSTALLING_NETWORK') && WP_INSTALLING_NETWORK) && !file_exists(WP_LANG_DIR . "/admin-{$cleaning_up}.mo")) {
        load_textdomain('default', WP_LANG_DIR . "/ms-{$cleaning_up}.mo", $cleaning_up);
        return $b_j;
    }
    if (is_admin() || wp_installing() || defined('WP_REPAIRING') && WP_REPAIRING) {
        load_textdomain('default', WP_LANG_DIR . "/admin-{$cleaning_up}.mo", $cleaning_up);
    }
    if (is_network_admin() || defined('WP_INSTALLING_NETWORK') && WP_INSTALLING_NETWORK) {
        load_textdomain('default', WP_LANG_DIR . "/admin-network-{$cleaning_up}.mo", $cleaning_up);
    }
    return $b_j;
}
