/**
 * @since 3.5.0
 *
 * @param int   $declarations_output
 * @param array $auto_draft_post
 * @return array
 */
function link_advanced_meta_box($declarations_output, $auto_draft_post = null)
{
    $form_name = get_post($declarations_output);
    $author_cache = array('errors' => null, 'in_modal' => false);
    $link_image = current_user_can('edit_post', $declarations_output);
    $auto_draft_post = wp_parse_args($auto_draft_post, $author_cache);
    /** This filter is documented in wp-admin/includes/media.php */
    $auto_draft_post = apply_filters('get_media_item_args', $auto_draft_post);
    $submatchbase = array();
    if ($auto_draft_post['in_modal']) {
        foreach (get_attachment_taxonomies($form_name) as $label_inner_html) {
            $enclosures = (array) get_taxonomy($label_inner_html);
            if (!$enclosures['public'] || !$enclosures['show_ui']) {
                continue;
            }
            if (empty($enclosures['label'])) {
                $enclosures['label'] = $label_inner_html;
            }
            if (empty($enclosures['args'])) {
                $enclosures['args'] = array();
            }
            $cluster_block_group = get_object_term_cache($form_name->ID, $label_inner_html);
            if (false === $cluster_block_group) {
                $cluster_block_group = wp_get_object_terms($form_name->ID, $label_inner_html, $enclosures['args']);
            }
            $relative_class = array();
            foreach ($cluster_block_group as $previousbyteoffset) {
                $relative_class[] = $previousbyteoffset->slug;
            }
            $enclosures['value'] = implode(', ', $relative_class);
            $enclosures['taxonomy'] = true;
            $submatchbase[$label_inner_html] = $enclosures;
        }
    }
    /*
