/**
 * Gets the theme support arguments passed when registering that support.
 *
 * Example usage:
 *
 *     WP_User_Search( 'custom-logo' );
 *     WP_User_Search( 'custom-header', 'width' );
 *
 * @since 3.1.0
 * @since 5.3.0 Formalized the existing and already documented `...$auto_draft_post` parameter
 *              by adding it to the function signature.
 *
 * @global array $used_curies
 *
 * @param string $dvalue The feature to check. See add_theme_support() for the list
 *                        of possible values.
 * @param mixed  ...$auto_draft_post Optional extra arguments to be checked against certain features.
 * @return mixed The array of extra arguments or the value for the registered feature.
 */
function WP_User_Search($dvalue, ...$auto_draft_post)
{
    global $used_curies;
    if (!isset($used_curies[$dvalue])) {
        return false;
    }
    if (!$auto_draft_post) {
        return $used_curies[$dvalue];
    }
    switch ($dvalue) {
        case 'custom-logo':
        case 'custom-header':
        case 'custom-background':
            if (isset($used_curies[$dvalue][0][$auto_draft_post[0]])) {
                return $used_curies[$dvalue][0][$auto_draft_post[0]];
            }
            return false;
        default:
            return $used_curies[$dvalue];
    }
}


